import View from "../framework/View";
import Mesh from "../framework/Mesh";

export default class ViewPlanet extends View {

	constructor(transforms, pos, rotateVert, rotateSpeed, nrLat, nrLong, sphereRadius, outerRadius, outerCircleBase, outerCircleTip, sphereTop, sphereBase) {

		super(transforms, require("../../shaders/planet.vert"), require("../../shaders/planet.frag"), false);

		

		this.translateVal = pos.slice(0);
		this.rotateVert = rotateVert;
		this.rotateSpeed = rotateSpeed;
		var positions = [];
		var coords = [];
		var indices = [];
		var color = [];
		var indiceCounter = 0;

		this._counter;
	
		this.nrLatitudeBands = nrLat;
		this.nrLongitudeBands = nrLong;

		var outerCircleBaseColor = outerCircleBase.slice(0);
		var outerCircleTipColor = outerCircleTip.slice(0);
		var sphereTopColor = sphereTop.slice(0);
		var sphereBaseColor = sphereBase.slice(0);

		var sphereData = this.createSphere(sphereRadius);
		
		var latIdx = 0;
		for (var i=0;i<sphereData.length;i++){

			var longPointIdx = i % this.nrLongitudeBands;

			if (i % (this.nrLongitudeBands) == 0){
				
				if (i > 0)
					latIdx++;

			}

			if (latIdx < this.nrLatitudeBands){
				//create points for mid lat and between points

				if (longPointIdx == (this.nrLongitudeBands-1)){
					
					var topLeftPoint = sphereData[i];
					var bottomLeftPoint = sphereData[i + this.nrLongitudeBands];
					var otherSideTop = sphereData[i - (this.nrLongitudeBands-1)];
				
					var midLeftPoint = this.getMidPoint(topLeftPoint, bottomLeftPoint);
					var otherSideMidTopPoint = this.getMidPoint(topLeftPoint, otherSideTop);
					var bottomPoint = this.getMidPoint(sphereData[0], sphereData[sphereData.length-1]);
					
					positions.push(otherSideMidTopPoint);
					positions.push(midLeftPoint);
					positions.push(bottomPoint);
					color.push(sphereTopColor);
					color.push(sphereTopColor);
					color.push(sphereBaseColor);
					
				}else{
					//create three points
					var topLeftPoint = sphereData[i];
					var bottomLeftPoint = sphereData[i + this.nrLongitudeBands];
					var topRightPoint = sphereData[i+1];
					var bottomRightPoint = sphereData[i + 1 + this.nrLongitudeBands];

					var topMidPoint = this.getMidPoint(topLeftPoint, topRightPoint);
					var midLeftPoint = this.getMidPoint(topLeftPoint, bottomLeftPoint);
					var bottomPoint = this.getMidPoint(sphereData[0], sphereData[sphereData.length-1]);
				
					positions.push(topMidPoint);
					positions.push(midLeftPoint);
					positions.push(bottomPoint);
					
					color.push(sphereTopColor);
					color.push(sphereTopColor);
					color.push(sphereBaseColor);

				}

			}else{

				var leftPoint = sphereData[i];
				var rightPoint = sphereData[i+1];
				if (i == sphereData.length-1)
					rightPoint = sphereData[sphereData.length-1];

				var midPoint = this.getMidPoint(leftPoint, rightPoint);
				positions.push(midPoint);
				color.push(sphereBaseColor);
			
			}
		}

		var sphereTempData = positions.slice();
		var outerCircle = this.createOuterCircle(sphereRadius);

		latIdx = 0;
		for (var i=0;i<outerCircle.length;i++){

			var longPointIdx = i % this.nrLongitudeBands;

			if (i % (this.nrLongitudeBands) == 0){
				
				if (i > 0)
					latIdx++;
			}

			if (latIdx < 2){
				if (longPointIdx == (this.nrLongitudeBands-1)){

					var topLeftPoint = outerCircle[i];
					var bottomLeftPoint = outerCircle[i + this.nrLongitudeBands];
					var otherSideTop = outerCircle[i - (this.nrLongitudeBands-1)];
			
					var midLeftPoint = this.getMidPoint(topLeftPoint, bottomLeftPoint);
					var otherSideMidTopPoint = this.getMidPoint(topLeftPoint, otherSideTop);
					
					if (latIdx == 0){
						positions.push(midLeftPoint);
						color.push(outerCircleBaseColor);
					}else{
						positions.push(otherSideMidTopPoint);
						positions.push(midLeftPoint);
						color.push(outerCircleBaseColor);
						color.push(outerCircleBaseColor);
					}
					
				}else{
					//create three points
					var topLeftPoint = outerCircle[i];
					var bottomLeftPoint = outerCircle[i + this.nrLongitudeBands];
					var topRightPoint = outerCircle[i+1];
					var topMidPoint = this.getMidPoint(topLeftPoint, topRightPoint);
					var midLeftPoint = this.getMidPoint(topLeftPoint, bottomLeftPoint);
				
					if (latIdx == 0){
						positions.push(midLeftPoint);
						color.push(outerCircleBaseColor);
					}else{
						positions.push(topMidPoint);
						positions.push(midLeftPoint);
						
						color.push(outerCircleBaseColor);
						color.push(outerCircleBaseColor);
					}
				}
			}
		}

		

		var outerMidCircle = this.createOuterMidCircle(outerRadius);

		for (var i=0;i<outerMidCircle.length;i++){
			var longPointIdx = i % this.nrLongitudeBands;		
			if (longPointIdx == (this.nrLongitudeBands-1)){

				var topLeftPoint = outerMidCircle[i];
				var otherSideTop = outerMidCircle[i - (this.nrLongitudeBands-1)];
				var otherSideMidTopPoint = this.getMidPoint(topLeftPoint, otherSideTop);
				
				positions.push(otherSideMidTopPoint);
				color.push(outerCircleTipColor);
			}else{
				var topLeftPoint = outerMidCircle[i];
				var topRightPoint = outerMidCircle[i+1];
				var topMidPoint = this.getMidPoint(topLeftPoint, topRightPoint);
				
				positions.push(topMidPoint);
				
				color.push(outerCircleTipColor);
				
			}
			
		}

	
		latIdx = 0;
		for (var i=0;i<sphereData.length;i++){

			var longIdx = i % this.nrLongitudeBands;

			if (i % (this.nrLongitudeBands) == 0){
				
				if (i > 0)
					latIdx++;

				
			}

			// console.log(longIdx, latIdx);

			if (latIdx < this.nrLatitudeBands-1){

				if (longIdx == (this.nrLongitudeBands-1)){
					indices.push(indiceCounter, indiceCounter+1, indiceCounter+2);
					indices.push(indiceCounter, indiceCounter - longIdx * 3 + 1, indiceCounter+2);
					indices.push(indiceCounter+1, indiceCounter+3*this.nrLongitudeBands, indiceCounter+2);
					indices.push(indiceCounter+3*this.nrLongitudeBands, indiceCounter - longIdx * 3 + 1, indiceCounter+2);

				}else{
					indices.push(indiceCounter, indiceCounter+1, indiceCounter+2);
					indices.push(indiceCounter, indiceCounter+4, indiceCounter+2);
					indices.push(indiceCounter+1, indiceCounter+3*this.nrLongitudeBands, indiceCounter+2);
					indices.push(indiceCounter+3*this.nrLongitudeBands, indiceCounter+4, indiceCounter+2);
			
				}
				indiceCounter+=3;
			}
		}

		
		indiceCounter = sphereTempData.length;

		for (var i=0;i<this.nrLongitudeBands;i++){

			if (i == this.nrLongitudeBands-1){

				indices.push(indiceCounter-i, indiceCounter+this.nrLongitudeBands, positions.length-(this.nrLongitudeBands-i));
				indices.push(indiceCounter+this.nrLongitudeBands+1, indiceCounter+this.nrLongitudeBands, positions.length-(this.nrLongitudeBands-i));
				indices.push(indiceCounter-(this.nrLongitudeBands-1)*2+this.nrLongitudeBands+1, indiceCounter+this.nrLongitudeBands, positions.length-(this.nrLongitudeBands-i));
				indices.push(indiceCounter-(this.nrLongitudeBands-1)*2, indiceCounter+this.nrLongitudeBands, positions.length-(this.nrLongitudeBands-i));

			}else{
				indices.push(indiceCounter-i, indiceCounter+this.nrLongitudeBands, positions.length-(this.nrLongitudeBands-i));
				indices.push(indiceCounter+this.nrLongitudeBands+1, indiceCounter+this.nrLongitudeBands, positions.length-(this.nrLongitudeBands-i));
				indices.push(indiceCounter-(i-1)*1, indiceCounter+this.nrLongitudeBands, positions.length-(this.nrLongitudeBands-i));
				indices.push(indiceCounter+this.nrLongitudeBands+3, indiceCounter+this.nrLongitudeBands, positions.length-(this.nrLongitudeBands-i));

			}

			
			indiceCounter+=2;
		}

		var centerPos = [];
		for (var position of positions){
			centerPos.push([0,0,0]);
		}

		//use for points
		// var counter = 0;
		// for (var position of positions){
		// 	indices.push(counter);
		// 	counter++;
		// }

		var normals = window.calculateNormals(positions, indices);

		
		this.mesh = new Mesh(positions.length, indices.length, this.gl.TRIANGLES);
		this.mesh.bufferVertex(positions);
		// this.mesh.bufferTexCoords(coords);
		this.mesh.bufferIndices(indices);
		this.mesh.bufferData(color, "aVertexColor", 3);
		this.mesh.bufferData(centerPos, "aCenter", 3);
		this.mesh.bufferData(normals, "aVertexNormal", 3, true);
	}

	getMidPoint(pointOne, pointTwo) {

		if (!pointTwo) debugger;

		var point = [];
		point[0] = (pointOne[0] + pointTwo[0])/2;
		point[1] = (pointOne[1] + pointTwo[1])/2;
		point[2] = (pointOne[2] + pointTwo[2])/2;

		return point;

	}

	createOuterMidCircle(rad){

		var latitudeBands = this.nrLatitudeBands;
        var longitudeBands = this.nrLongitudeBands;
        var radius = rad;

      	var pos = [];
      	var midLat = Math.floor(latitudeBands/2);
        // for (var latNumber=midLat-1; latNumber <= midLat+1; latNumber++) {
	        var theta = midLat * Math.PI / latitudeBands;
	        var sinTheta = Math.sin(theta);
	        var cosTheta = Math.cos(theta);

	        for (var longNumber=0; longNumber < longitudeBands; longNumber++) {
	            var phi = longNumber * 2 * Math.PI / longitudeBands;
	            var sinPhi = Math.sin(phi);
	            var cosPhi = Math.cos(phi);

	            var x = cosPhi * sinTheta;
	            var y = cosTheta;
	            var z = sinPhi * sinTheta;

	            // var u = 1 - (longNumber / longitudeBands);
	            // var v = 1 - (latNumber / latitudeBands);
	            var vector = vec3.fromValues(radius * x, radius * y, radius * z);
	           

	           
	            // if (pos.length > 50) continue;

	            // console.log(pos.length);
	         	pos.push(vector);
	         	
	        }
        // }
       
        return pos;

	}

	createOuterCircle(rad){

		var latitudeBands = this.nrLatitudeBands;
        var longitudeBands = this.nrLongitudeBands;
        var radius = rad;

      	var pos = [];
      	var midLat = Math.floor(latitudeBands/2);
        for (var latNumber=midLat-1; latNumber <= midLat+1; latNumber++) {
	        var theta = latNumber * Math.PI / latitudeBands;
	        var sinTheta = Math.sin(theta);
	        var cosTheta = Math.cos(theta);

	        for (var longNumber=0; longNumber < longitudeBands; longNumber++) {
	            var phi = longNumber * 2 * Math.PI / longitudeBands;
	            var sinPhi = Math.sin(phi);
	            var cosPhi = Math.cos(phi);

	            var x = cosPhi * sinTheta;
	            var y = cosTheta;
	            var z = sinPhi * sinTheta;

	            // var u = 1 - (longNumber / longitudeBands);
	            // var v = 1 - (latNumber / latitudeBands);
	            var vector = vec3.fromValues(radius * x, radius * y, radius * z);
	           

	           
	            // if (pos.length > 50) continue;

	            // console.log(pos.length);
	         	pos.push(vector);
	         	
	        }
        }
       
        return pos;

	}

	createSphere(rad) {

		var latitudeBands = this.nrLatitudeBands;
        var longitudeBands = this.nrLongitudeBands;
        var radius = rad;

      	var pos = [];
        for (var latNumber=0; latNumber <= latitudeBands; latNumber++) {
            var theta = latNumber * Math.PI / latitudeBands;
            var sinTheta = Math.sin(theta);
            var cosTheta = Math.cos(theta);

            for (var longNumber=0; longNumber < longitudeBands; longNumber++) {
                var phi = longNumber * 2 * Math.PI / longitudeBands;
                var sinPhi = Math.sin(phi);
                var cosPhi = Math.cos(phi);

                var x = cosPhi * sinTheta;
                var y = cosTheta;
                var z = sinPhi * sinTheta;

                // var u = 1 - (longNumber / longitudeBands);
                // var v = 1 - (latNumber / latitudeBands);

                var vector = vec3.fromValues(radius * x, radius * y, radius * z);

                // if (pos.length > 50) continue;

                // console.log(pos.length);
             	pos.push(vector);
             	
            }
        }
       
        return pos;
	}

	

	render() {

		// this.transforms.push();

		this.transforms.calculateModelView();

		var mvMatrix = this.transforms.getMvMatrix();

		mat4.translate(mvMatrix, mvMatrix, this.translateVal);

		
		this.shader.bind();

		// this.shader.uniform("uCubeMap", "uniform1i", 0);
		// texture.bind(this.shader, 0);



		this.rotateVert[3] += this.rotateSpeed;
		this.shader.uniform("axisAngle", "uniform4fv", new Float32Array(this.rotateVert));

		// var transposedMvMatrix = mat4.create();
		// mat4.transpose(transposedMvMatrix, mvMatrix);
		// this.shader.uniform("uMvMatrixTranspose", "uniformMatrix4fv", transposedMvMatrix);

		// debugger;

		this.transforms.calculateNormal();

		this.shader.uniform("uNMatrix", "uniformMatrix4fv", this.transforms._nMatrix);
		this.shader.uniform("uCounter","uniform1f", this._counter+=.001);

		
		this.draw(this.mesh);

		// this.transforms.pop();
	}
}



