import View from "../framework/View";
import Mesh from "../framework/Mesh";

export default class ViewPost extends View {

	constructor(transforms) {

		super(transforms, require("../../shaders/copy.vert"), require("../../shaders/post.frag"));

		this._counter = 0;
		var positions = [];
		var coords = [];
		var indices = [0, 1, 2, 0, 2, 3];
		

		var size = 1;
		positions.push([-size, -size, 0]);
		positions.push([ size, -size, 0]);
		positions.push([ size,  size, 0]);
		positions.push([-size,  size, 0]);

		coords.push([0, 0]);
		coords.push([1, 0]);
		coords.push([1, 1]);
		coords.push([0, 1]);

		// debugger;
		this.mesh = new Mesh(positions.length, indices.length, this.gl.TRIANGLES);
		this.mesh.bufferVertex(positions);
		this.mesh.bufferTexCoords(coords);
		this.mesh.bufferIndices(indices);
	}

	render(planetTexture, triangleTexture, scratchTexture) {

		// this.transforms.push();

		this.shader.bind();


		this.shader.uniform("uTexturePlanet", "uniform1i", 0);
		planetTexture.bind(this.shader, 0);

		this.shader.uniform("uTextureTriangle", "uniform1i", 1);
		triangleTexture.bind(this.shader, 1);

		this.shader.uniform("uTextureScratch", "uniform1i", 2);
		scratchTexture.bind(this.shader, 2);

		this.shader.uniform("uCounter", "uniform1f", this._counter+=.01);

		this.draw(this.mesh);

		// this.transforms.pop();
	}
}



