import Scene from "./framework/Scene";

import ViewPlanet from "./views/ViewPlanet";
import ViewTriangles from "./views/ViewTriangles";
import ViewCopy from "./views/ViewCopy";
import ViewPost from "./views/ViewPost";
import ViewPostBlurH from "./views/ViewPostBlurH";
import ViewPostBlurV from "./views/ViewPostBlurV";

import CameraInteractor from "./framework/CameraInteractor";
// import MouseInteractor from "./framework/MouseInteractor";
// import KeyboardInteractor from "./framework/KeyboardInteractor";
import SceneTransforms from "./framework/SceneTransforms";
import Framebuffer from "./framework/Framebuffer";
import CubeMap from './framework/CubeMap';
import SpectrumAnalyser from "./framework/SpectrumAnalyser";
import Texture from "./framework/Texture";

export default class SceneMain extends Scene {
	constructor() {

		super();
		this.onResize();
		window.addEventListener('resize', () => {
			this.onResize();
		});

		this.hasSaved = false;



		this.camera.goHome([0,0,6]);

		this.cameraInteractor = new CameraInteractor(this.camera, this.canvas);

	

		this.transforms = new SceneTransforms(this.canvas);

		this.orthoTransforms = new SceneTransforms(this.canvas);

		this._vPlanets = [];

		this._loading = true;


		var img = new Image();
		img.onload = () => {

			console.log('laoded');
			this.scratchTextureSrc = img;
			this.initTextures();
			this.initViews();

			this._loading = false;
		};
		img.src = 'assets/scratchtexture-12.jpg';
		

		



	}

	
	initTextures() {

		var size = 1024;
	
		this.scratchTexture = new Texture(this.scratchTextureSrc, false);
		this.fboTriangles = new Framebuffer(size, size, this.gl.NEAREST, this.gl.NEAREST, this.gl.FLOAT);
		this.fboPlanets = new Framebuffer(size/4, size/4, this.gl.NEAREST, this.gl.NEAREST, this.gl.FLOAT);
		this.fboFinal = new Framebuffer(size, size, this.gl.NEAREST, this.gl.NEAREST, this.gl.FLOAT);

		this.fboHorizontalBlur = new Framebuffer(size, size, this.gl.NEAREST, this.gl.NEAREST, this.gl.FLOAT);
		// this.fboVerticalBlur = new Framebuffer(size, size, this.gl.NEAREST, this.gl.NEAREST, this.gl.FLOAT);
	

			
	}

	initViews() {

		this._vPost = new ViewPost(this.orthoTransforms);
		this._vCopy = new ViewCopy(this.orthoTransforms);
		this._vTriangles = new ViewTriangles(this.transforms);

		this._vPostBlurH = new ViewPostBlurH(this.orthoTransforms);
		this._vPostBlurV = new ViewPostBlurV(this.orthoTransforms);

	

		var pos = [-1.5, 0, 0];
		var rotateVert = [1.4, 1, .8, 0];
		var rotateSpeed = .7;
		var lat = 14;
		var lng = 14;
		var innerRad = 1.2;
		var outerRad = 1.4;
		var outerCircleBaseColor = [.8,.5,.5];
		var outerCircleTipColor = [.8,.7,.7];
		var sphereTopColor = [.8,.5,.5];
		var sphereBaseColor = [.1,.2,.3];
		var planet = new ViewPlanet(this.transforms, pos, rotateVert, rotateSpeed, lat, lng, innerRad, outerRad, outerCircleBaseColor, outerCircleTipColor, sphereTopColor, sphereBaseColor);
		this._vPlanets.push(planet);

		// var pos = [0, 0, 0];
		// var rotateVert = [.2, .5, .1, 0];
		// var rotateSpeed = -.5;
		// var lat = 14;
		// var lng = 14;
		// var innerRad = .8;
		// var outerRad = 1.0;
		// var outerCircleBaseColor = [.4,.5,.5];
		// var outerCircleTipColor = [.8,.7,.9];
		// var sphereTopColor = [.4,.5,.5];
		// var sphereBaseColor = [.1,.2,.3];
		// planet = new ViewPlanet(this.transforms, pos, rotateVert, rotateSpeed, lat, lng, innerRad, outerRad, outerCircleBaseColor, outerCircleTipColor, sphereTopColor, sphereBaseColor);
		// this._vPlanets.push(planet);

		var pos = [1.3, .4, 0];
		var rotateVert = [.2, .3, 1.3, 0];
		var rotateSpeed = -1.0;
		var lat = 14;
		var lng = 14;
		var innerRad = 1.6;
		var outerRad = 1.8;
		var outerCircleBaseColor = [.1,.5,.5];
		var outerCircleTipColor = [.8,.7,.9];
		var sphereTopColor = [.1,.5,.5];
		var sphereBaseColor = [.1,.2,.3];
		planet = new ViewPlanet(this.transforms, pos, rotateVert, rotateSpeed, lat, lng, innerRad, outerRad, outerCircleBaseColor, outerCircleTipColor, sphereTopColor, sphereBaseColor);
		this._vPlanets.push(planet);



	

	}

	update() {

		super.update();

	}

	render() {

		if (this._loading) return;

		this.gl.disable(this.gl.DEPTH_TEST);

		this.gl.enable(this.gl.BLEND);

		


		this.gl.viewport(0, 0, this.gl.viewportWidth, this.gl.viewportHeight);

		this.gl.clearColor( 0, 0, 0, 1 );
		this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);


		// this.transforms.push();
		this.transforms.setCamera(this.camera);

		// debugger;

		this.camera.updatePerspective(this.gl.viewportWidth, this.gl.viewportHeight);

		// this.transforms.updatePerspective(this.gl.viewportWidth, this.gl.viewportHeight);
	
		// this.transforms.calculateModelView();

		// this._vMap.render(this.fboTarget.getTexture());


		
		this.gl.enable(this.gl.DEPTH_TEST);

		this.gl.disable(this.gl.BLEND);

		// this._vSkyBox.render(this.cubeMap);
		this.gl.viewport(0, 0, this.fboTriangles.width, this.fboTriangles.height);


		this.fboTriangles.bind();
		this.gl.clearColor( 0, 0, 0, 1 );
		this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);
		this._vTriangles.render();
		this.fboTriangles.unbind();

		this.gl.viewport(0, 0, this.fboPlanets.width, this.fboPlanets.height);
		this.fboPlanets.bind();
		this.gl.clearColor( 0, 0, 0, 1 );
		this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);
		for (var planet of this._vPlanets) planet.render();

		this.fboPlanets.unbind();

		this.orthoTransforms.setCamera(this.orthoCamera);

		// this.gl.viewport(0, 0, this.fboFinal.width, this.fboFinal.height);
		// this.fboFinal.bind();
		// this.gl.clearColor( 0, 0, 0, 1 );
		// this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);
		// this._vPost.render(this.fboPlanets.getTexture(), this.fboTriangles.getTexture(), this.scratchTexture);

		// this.fboFinal.unbind();

		// this.gl.viewport(0, 0, this.fboHorizontalBlur.width, this.fboHorizontalBlur.height);
		// this.fboHorizontalBlur.bind();
		// this.gl.clearColor( 0, 0, 0, 1 );
		// this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);
		// this._vPostBlurH.render(this.fboFinal.getTexture());

		// this.fboHorizontalBlur.unbind();


		this.gl.viewport(0, 0, this.gl.viewportWidth, this.gl.viewportHeight);

		this.gl.clearColor( 0, 0, 0, 1 );
		this.gl.clear(this.gl.COLOR_BUFFER_BIT | this.gl.DEPTH_BUFFER_BIT);

		this._vPost.render(this.fboPlanets.getTexture(), this.fboTriangles.getTexture(), this.scratchTexture);

		
		// this._vCopy.render(this.fboTriangles.getTexture());
		// this._vPostBlurV.render(this.fboHorizontalBlur.getTexture());





		




		// this._vMap.render(this.fboTarget.getTexture());

		
		// this.transforms.pop();

		//POST-Processing
		// this.swapFbos();

	}

	

}


