import View from "../framework/View";
import Mesh from "../framework/Mesh";

export default class ViewTriangles extends View {

	constructor(transforms) {

		super(transforms, require("../../shaders/triangles.vert"), require("../../shaders/triangles.frag"));
		var positions = [];
		var coords = [];
		var colors = [];
		var effect = [];
		
		var indices = [];

		for (var i=0;i<28;i+=3){
			var effectRand = Math.random();
			positions.push([Math.random() * 2 - 1, Math.random() * 2 - 1,  Math.random() * 2 - 1]);
			positions.push([ Math.random() * 2 - 1, Math.random() * 2 - 1,  Math.random() * 2 - 1]);
			positions.push([ Math.random() * 2 - 1, Math.random() * 2 - 1,  Math.random() * 2 - 1]);

			indices.push(i, i+1, i+2);

			colors.push([Math.random(), Math.random(), Math.random()]);
			colors.push([Math.random(), Math.random(), Math.random()]);
			colors.push([Math.random(), Math.random(), Math.random()]);

			effect.push([effectRand, effectRand]);
			effect.push([effectRand, effectRand]);
			effect.push([effectRand, effectRand]);


		}
		
		this.counter = 0;

		this.mesh = new Mesh(positions.length, indices.length, this.gl.TRIANGLES);
		this.mesh.bufferVertex(positions);
		// this.mesh.bufferTexCoords(coords);
		this.mesh.bufferIndices(indices);
		this.mesh.bufferData(colors, 'aVertexColor', 3);
		this.mesh.bufferData(effect, 'aVertexEffect', 2);
	}

	render() {

		// this.transforms.push();
		this.transforms.calculateModelView();

		var mvMatrix = this.transforms.getMvMatrix();

		this.shader.bind();

		

		this.shader.uniform("uCounter", "uniform1f", this.counter+=.001);
		

		this.draw(this.mesh);

		// this.transforms.pop();
	}
}



